import {ResponseError} from '@github-ui/react-core/future/response-error'
import {useMutation} from '@github-ui/react-query'
import {reactFetch} from '@github-ui/verified-fetch'

import {deleteIssueFieldRoute} from '../routes/delete-field-route'

export async function deleteIssueField(issueFieldId: string, organization: string) {
  const pathname = deleteIssueFieldRoute.generatePath({org: organization, issueFieldId})
  const init = {
    method: 'DELETE',
  }
  const response = await reactFetch(pathname, init)
  if (!response.ok) {
    // try to extract error details from the response body if there are any
    let errorDetails = ''
    try {
      const data = await response.json()
      if (data && data.error) errorDetails = `: ${data.error}`
    } catch {
      // ignore JSON parsing errors for non-JSON responses
    }
    throw new ResponseError(`Failed to delete issue field ${errorDetails}`, response)
  }
  return response.json()
}

export function useDeleteIssueFieldMutation(organization: string) {
  return useMutation({
    mutationFn: async (issueFieldId: string) => {
      return deleteIssueField(issueFieldId, organization)
    },
  })
}
