import {
  createIssueTypePickerItemLeadingVisual,
  NoTypeIndicator,
} from '@github-ui/item-picker-issue-type/IssueTypeIndicators'
import {Link} from '@github-ui/react-core/link'
import {InfoIcon, PencilIcon} from '@primer/octicons-react'
import {IconButton, Tooltip} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import type {RefObject} from 'react'

import {Resources} from '../constants/strings'
import type {IssueTypeWithPinnedCount} from '../types/field-visibility'
import styles from './IssueFieldsPinToIssueTypes.module.css'

type IssueFieldsPinToIssueTypesProps = {
  issueTypes: IssueTypeWithPinnedCount[]
  pinnedToNoTypeIssues: boolean
  organizationLogin: string
  onEditClick?: () => void
  disabled?: boolean
  editButtonRef?: RefObject<HTMLButtonElement | null>
}

export function IssueFieldsPinToIssueTypes({
  issueTypes,
  pinnedToNoTypeIssues,
  organizationLogin,
  onEditClick,
  disabled = false,
  editButtonRef,
}: IssueFieldsPinToIssueTypesProps) {
  const isEmpty = issueTypes.length === 0 && !pinnedToNoTypeIssues

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <div className={styles.headerContent}>
          <span className={styles.heading}>{Resources.fieldPinToIssueTypesLabel}</span>
          <p className={styles.description}>
            {Resources.fieldPinToIssueTypesDescriptionPrefix}
            <Link to={`/organizations/${organizationLogin}/settings/issue-types`} className="Link--inTextBlock">
              {Resources.fieldPinToIssueTypesDescriptionLink}
            </Link>
            {Resources.fieldPinToIssueTypesDescriptionSuffix}
          </p>
        </div>
        {disabled ? (
          <Tooltip text={Resources.fieldPinToIssueTypesEditDisabledTooltip} type="description">
            <IconButton
              aria-label={Resources.fieldPinToIssueTypesEditLabel}
              icon={PencilIcon}
              onClick={e => e.preventDefault()}
              inactive
              aria-disabled
            />
          </Tooltip>
        ) : (
          <IconButton
            ref={editButtonRef}
            aria-label={Resources.fieldPinToIssueTypesEditLabel}
            icon={PencilIcon}
            onClick={onEditClick}
          />
        )}
      </div>
      <div className={styles.listContainer}>
        {isEmpty ? (
          <>
            <Blankslate border={false} size="small" className={styles.blankslate}>
              <Blankslate.Description>{Resources.fieldPinToIssueTypesEmptyBlankslate}</Blankslate.Description>
            </Blankslate>
            <div className={styles.infoFooter}>
              <InfoIcon size={16} />
              <span>{Resources.fieldPinToIssueTypesEmptyWarning}</span>
            </div>
          </>
        ) : (
          <ul className={styles.list}>
            {pinnedToNoTypeIssues && (
              <li className={styles.listItem}>
                <NoTypeIndicator />
                <span className={styles.listItemText}>{Resources.fieldPinToIssueTypesNoType}</span>
              </li>
            )}
            {issueTypes.map(issueType => {
              const IssueTypeIndicator = createIssueTypePickerItemLeadingVisual(issueType.color)
              return (
                <li key={issueType.id} className={styles.listItem}>
                  <IssueTypeIndicator />
                  <span className={styles.listItemText}>{issueType.name}</span>
                </li>
              )
            })}
          </ul>
        )}
      </div>
    </div>
  )
}
