import {Dialog} from '@primer/react'
import {useCallback} from 'react'

import {Resources} from '../constants/strings'

type IssueFieldEditConfirmationDialogProps = {
  isOpen: boolean
  onClose: () => void
  onConfirm: () => void
}

export function IssueFieldEditConfirmationDialog({isOpen, onClose, onConfirm}: IssueFieldEditConfirmationDialogProps) {
  const handleConfirm = useCallback(() => {
    onConfirm()
    onClose()
  }, [onConfirm, onClose])

  const handleClose = useCallback(() => {
    onClose()
  }, [onClose])

  if (!isOpen) {
    return null
  }

  return (
    <Dialog
      title={Resources.globalEditConfirmationDialogTitle}
      width="large"
      onClose={handleClose}
      footerButtons={[
        {buttonType: 'default', content: Resources.cancelButton, onClick: handleClose},
        {
          buttonType: 'primary',
          content: Resources.globalEditConfirmationButton,
          onClick: handleConfirm,
        },
      ]}
    >
      <div>{Resources.globalEditConfirmationDialogBody}</div>
    </Dialog>
  )
}
