import {lazyWithPreload} from '@github-ui/react-core/lazy-with-preload'

// Lazy load IssueFieldOptions to make it SSR-friendly.
// Since IssueFieldOptions is a named export, we need to transform it to default export.
export const LazyIssueFieldOptions = lazyWithPreload(async () => {
  const m = await import('./IssueFieldOptions')
  return {default: m.IssueFieldOptions}
})

export const preloadIssueFieldOptions = LazyIssueFieldOptions.preload
