import {useEffect, useRef, useState} from 'react'

import {
  ISSUE_FIELD_DESCRIPTION_LIMIT,
  ISSUE_FIELD_NAME_LIMIT,
  RESERVED_NAMES,
  VALID_NAME_REGEX,
} from '../constants/constants'
import {Resources} from '../constants/strings'

const schema = {
  name: [
    {
      validation: (value: string) => !value,
      errorMessage: Resources.nameEmptyErrorMessage,
    },
    {
      validation: (value: string) => RESERVED_NAMES.includes(value.trim().toLowerCase()),
      errorMessage: Resources.nameReservedError,
    },
    {
      validation: (value: string, existingNames?: string[]) =>
        existingNames?.some(name => name.toLowerCase() === value.trim().toLowerCase()),
      errorMessage: Resources.nameTakenError,
    },
    {
      validation: (value: string) => value.length > ISSUE_FIELD_NAME_LIMIT,
      errorMessage: Resources.nameTooLongErrorMessage(ISSUE_FIELD_NAME_LIMIT),
    },
    {
      validation: (value: string) => !VALID_NAME_REGEX.test(value),
      errorMessage: Resources.nameInvalidCharactersError,
    },
  ],
  description: [
    {
      validation: (value: string) => value.length > ISSUE_FIELD_DESCRIPTION_LIMIT,
      errorMessage: Resources.descriptionTooLongErrorMessage(ISSUE_FIELD_DESCRIPTION_LIMIT),
    },
  ],
}

export const useInputFieldsErrors = (existingNames: string[]) => {
  const fieldNameRef = useRef<HTMLInputElement>(null)
  const fieldDescriptionRef = useRef<HTMLTextAreaElement>(null)

  const [nameError, setNameError] = useState<string>('')
  const [descriptionError, setDescriptionError] = useState<string>('')

  const [shouldFocusError, setShouldFocusError] = useState<boolean>(false)

  useEffect(() => {
    const focusInvalidInputField = () => {
      const invalidFieldRef = nameError ? fieldNameRef : descriptionError ? fieldDescriptionRef : null
      if (invalidFieldRef && invalidFieldRef.current) {
        invalidFieldRef.current?.focus({preventScroll: false})
      }
    }

    if (shouldFocusError) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setShouldFocusError(false)
      focusInvalidInputField()
    }
  }, [descriptionError, nameError, shouldFocusError])

  const validate = () => {
    const name = fieldNameRef.current?.value || ''
    const description = fieldDescriptionRef.current?.value || ''

    const nameFieldError = schema.name.find(({validation}) => validation(name, existingNames))?.errorMessage || ''
    const descriptionFieldError = schema.description.find(({validation}) => validation(description))?.errorMessage || ''

    setNameError(nameFieldError)
    setDescriptionError(descriptionFieldError)

    return !nameFieldError && !descriptionFieldError
  }

  return {
    fieldNameRef,
    fieldDescriptionRef,
    nameError,
    descriptionError,
    setNameError,
    setDescriptionError,
    setShouldFocusError,
    validate,
  }
}
