import {isFeatureEnabled} from '@github-ui/feature-flags'
import {AllKnownTypes, type KnownType} from '@github-ui/issue-fields-shared/issue-field'
import {ActionList, ActionMenu, FormControl} from '@primer/react'
import {useId, useMemo} from 'react'

import {Resources} from '../constants/strings'

type IssueFieldDataTypeProps = {
  disabled?: boolean
  type: KnownType
  setType: (type: KnownType) => void
  ref?: React.Ref<HTMLButtonElement>
}

export function IssueFieldDataType({ref: forwardedRef, type, setType, disabled = false}: IssueFieldDataTypeProps) {
  const labelId = useId()
  const buttonId = useId()
  const multiSelectEnabled = isFeatureEnabled('issue_fields_multi_select')
  const availableTypes = useMemo(
    () => (multiSelectEnabled ? AllKnownTypes : AllKnownTypes.filter(t => t.type !== 'multi_select')),
    [multiSelectEnabled],
  )

  return (
    <FormControl disabled={disabled}>
      <FormControl.Label id={labelId}>{Resources.typeLabel}</FormControl.Label>
      <ActionMenu>
        <ActionMenu.Button
          id={buttonId}
          ref={forwardedRef}
          leadingVisual={type.icon}
          disabled={disabled}
          aria-labelledby={`${labelId} ${buttonId}`}
        >
          {type.displayName}
        </ActionMenu.Button>
        <ActionMenu.Overlay>
          <ActionList selectionVariant="single" role="menu" aria-label={Resources.typeLabel}>
            {availableTypes.map(knownType => (
              <ActionList.Item
                key={knownType.type}
                role="menuitemradio"
                selected={type === knownType}
                aria-checked={type === knownType}
                onSelect={() => setType(knownType)}
              >
                <ActionList.LeadingVisual>
                  <knownType.icon size={16} />
                </ActionList.LeadingVisual>
                {knownType.displayName}
              </ActionList.Item>
            ))}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
    </FormControl>
  )
}
