import type {IssueField} from '@github-ui/issue-fields-shared/issue-field'
import {mainQuery} from '@github-ui/react-core/future/main-query'

import {issueFieldsSettingsAppBuilder} from '../config/app-builder'
import type {IssueTypeWithPinnedCount} from '../types/field-visibility'
import type {Organization} from '../types/organization'

export type IssueFieldsSettingsEditResponse = {
  field: IssueField
  organization: Organization
  fields: IssueField[]
  orgPinnedFieldsEnabled?: boolean
  issueTypes?: IssueTypeWithPinnedCount[]
  pinnedIssueTypeIds?: number[]
  pinToNoTypeIssues?: boolean
}

export const issueFieldsSettingsEditRoute = issueFieldsSettingsAppBuilder.createQueryRouteConfig(
  'issueFieldsSettingsEditRoute',
  {
    path: '/organizations/:org/settings/issue-fields/:id',
    queries: [mainQuery<IssueFieldsSettingsEditResponse>()],
  },
)
